Switching to current revision via action=parse. Script below gathers wikitext for each August page and counts twitter/x post references.

import requests
import re

API = "https://en.wikipedia.org/w/api.php"
pages = [f"August {i}" for i in range(1, 32)]
TWITTER_RE = re.compile(r"https?://(?:www\.)?(?:twitter\.com|x\.com)/[^/]+/status/\d+")
ARCHIVE_RE = re.compile(r"https?://web\.archive\.org/web/\d+/(https?://(?:www\.)?(?:twitter\.com|x\.com)/[^/]+/status/\d+)")


def get_current_wikitext(title):
    params = {
        "action": "parse",
        "page": title,
        "prop": "wikitext",
        "format": "json"
    }
    r = requests.get(API, params=params)
    r.raise_for_status()
    data = r.json()
    return data.get("parse", {}).get("wikitext", {}).get("*", "")


def count_twitter_refs(text):
    return len(TWITTER_RE.findall(text)) + len(ARCHIVE_RE.findall(text))

per_page = {}
total = 0
for title in pages:
    wt = get_current_wikitext(title)
    c = count_twitter_refs(wt)
    per_page[title] = c
    total += c

print("Per-page counts:")
for k, v in per_page.items():
    if v:
        print(f"{k}: {v}")
print("Total:", total)
